// === Tab: mySketch ===
//Luminous tree
const sketch = (p) => {
    let G;
    let H = 2048;
    let W = 2048;

    let min_width;

    let T;

    let SEED;

    let SPL = 0.67;

    let stars = [];
    let tps;

    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowWidth*.75);
        min_width = p.min(p.width, p.height);
        G = p.createGraphics(W, H);

        SEED = p.random(998244353);

        p.randomSeed(SEED);
        p.noiseSeed(SEED); 


        G.noStroke();
        tps = p.random();
        if(tps < .5){
            T = new Tree(W/2, H*(SPL), W*0.65);
        }
        else{
            T = new Tree(W/2, H*(SPL), W*0.65);
        }

        let BG_COL = [
            "#05052A", "#000010", "#010525"
        ];
        let bg_grad = G.drawingContext.createLinearGradient(0, 0, 0, H);
        bg_grad.addColorStop(0.0, BG_COL[0]);
        bg_grad.addColorStop(SPL, BG_COL[1]);
        bg_grad.addColorStop(1, BG_COL[2]);
        G.drawingContext.fillStyle = bg_grad;
        G.rect(0, 0, W, H);
        G.drawingContext.fillStyle = "";

        G.rectMode(p.CENTER);
        let msc = p.pow(2, 8);
        let os1 = p.random();

        for(let k=0;k < 8;++k){
            let sc = p.pow(2, k);
            for(let x=-0.5+1e-3;x<=0.5;x+=1/sc){
                for(let y=SPL-.5+1e-3;y<=.5;y+=1/sc){
                    let v = p.noise((x+os1)*2*sc, y*.2*sc);
                    G.fill(
                        50,
                        50,
                        50,
                        v*sc/msc*(8.+ (y - SPL + .5)*30),
                    )
                    G.rect(W/2+x*W, H/2+y*H, W/sc, H/sc);
                }
            }
        }
        G.blendMode(p.BLEND);
        for(let i=0;i<300;++i){
            stars.push(new Star());
        }
    };

    p.windowResized = () => {
        p.resizeCanvas(p.width, p.height);
        min_width = p.min(p.width, p.height);
    }

    let cmode = 0;
    let smode = 1;
    p.draw = () => {
        p.blendMode(p.BLEND);
        p.background(0);
        T.update();
        T.display();

        p.image(G, 0, 0, p.width, p.height, 0, 0, W, H);

        if(smode == 1){
            for(let i=0;i<300;++i){
                stars[i].display();
            }
        }

        if(cmode == 1){
            p.blendMode(p.SOFT_LIGHT);
            p.fill(0, 200);
            p.rect(0,0,p.width,p.height);
        }
        else if(cmode == 2){
            p.blendMode(p.BURN);
            p.fill(0, 150);
            p.rect(0,0,p.width,p.height);
        }
    };

    p.keyPressed = () => {
        if(p.key == 's') {
            p.save("luminous_tree.jpg");
        }
        if(p.key == 'c') {
            cmode = (cmode + 1) % 3;
        }
        if(p.key == 'x') {
            smode = smode ^ 1;
        }
    }

    class Tree {
        pos;
        width;
        particles;
        branch_color;
        leaf_color;
        init_y;

        sub_colors;
        sub_offset;
        sub_radius;

        mx_step;
        step;
        nscale;
        time;
        additional_step;

        bias;

        base_color;
        base_leaf;
        white_v;
        leaf_dir;

        constructor(x, y, width){
            this.pos = p.createVector(x, y);
            this.width = width;
            this.particles = [];
            this.particles.push(
                new TreeParticle(x, y, p.HALF_PI, width*p.random(0.1, 0.15))//0.12
            );
            this.init_y = y;

            this.mx_step = 500;
            this.step = width / this.mx_step;
            this.nscale = 3 / width;
            this.time = 0;
            this.additional_step = p.int(p.random(150, 250));

            this.bias = 0;

            this.base_color = [1, 1, 1];
            let sel = p.random();
            if(sel < 0.2){
                this.base_color = [1, .7, .2];
                if(sel<0.1){
                    this.base_leaf = [.8, .4, .2];
                }
                else{
                    this.base_leaf = [.4, .8, .2];
                }

                this.white_v = 10;
            }
            else if(sel < 0.4){
                this.base_color = [.5, .3, .8];
                this.base_leaf = [.1, .8, .3];
                this.white_v = 50;
            }
            else if(sel < 0.6){
                this.base_color = [.1, .7, 1];
                this.base_leaf = [.1, .4, 1];
                this.white_v = 10;
            }
            else if(sel < 0.8){
                this.base_color = [.2, .7, .3];
                this.base_leaf = [.8, .2, .6];
                this.white_v = 10;
            }
            else{
                this.base_color = [.8, .5, .3];
                this.base_leaf = [.4, .8, .2];
                this.white_v = 10;
            }

            let red = p.random(30, 50) * this.base_color[0];
            let green = p.random(30, 50) * this.base_color[1];
            let blue = p.random(30, 50) * this.base_color[2];

            this.branch_color = p.color(
                red, green, blue, 30
            );
            this.sub_colors = [];
            this.sub_offset = [];
            this.sub_radius = [];



            for(let i=0;i<6;++i){
                this.sub_colors.push(p.color(
                    p.random(10, 150)*this.base_color[0],
                    p.random(10, 150)*this.base_color[1],
                    p.random(10, 150)*this.base_color[2],
                    20
                ));
                if(i%2==0){
                    this.sub_offset.push(p.random(0.3, 0.5));
                }
                else{
                    this.sub_offset.push(p.random(-0.5, -0.3));
                }
                this.sub_radius.push(0.12, 0.17);
            }

            this.leaf_dir = p.random(.2, .4);
        }

        update(){
            if(this.time == this.mx_step){
                let pl = this.particles.length;
                for(let i=0;i<pl;++i){
                    this.particles[i].radius = this.width*p.random(0.002, 0.006);
                    this.leaf_color = p.color(
                        p.random(10, 150) * this.base_leaf[0],
                        p.random(10, 150) * this.base_leaf[1],
                        p.random(10, 150) * this.base_leaf[2],
                        50
                    );

                    this.particles[i].angle = p.HALF_PI;

                    for(let j=0;j<2;++j){
                        this.particles.push(
                            new TreeParticle(
                                this.particles[i].pos.x + p.randomGaussian(0, 1) * this.width / 30,
                                this.particles[i].pos.y + p.randomGaussian(0, 1) * this.width / 30,
                                -p.HALF_PI,
                                this.width*p.random(0.002, 0.006)
                            )
                        )
                    }
                }
                this.time += 1;
                return;
            }
            if(this.time >= this.mx_step) {
                if(this.time > this.mx_step+this.additional_step) return;
                let osx = p.randomGaussian(0, 0.1) * this.width / 30;
                //let ratio = (this.time - this.mx_step) / this.additional_step;
                for(let i=0;i<this.particles.length;++i){
                    if(this.particles[i].pos.y > H*SPL){continue;}
                    this.particles[i].pos.x += osx,
                    this.particles[i].pos.y += this.leaf_dir;// * ratio;
                }
                this.time += 1;
                return;
            }

            if(this.time > this.mx_step * 0.5){
                this.particles[0].radius *= 0.99;
            }
            for(let i=0;i<this.particles.length;++i){
                if(i == 0 && this.time < this.mx_step * 0.25 || this.particles.length <= 10){
                    this.particles[i].angle += (p.randomGaussian(0, 0.05)) * 0.001;
                }
                else{
                    this.particles[i].angle += (p.randomGaussian(this.bias, 0.3)) * 0.3;
                }
                //this.particles[i].angle = p.constrain(this.particles[i].angle, -p.PI/6, p.PI*1.17);
                this.particles[i].pos.add(p.createVector(
                    this.step*p.cos(this.particles[i].angle),
                    -this.step*p.sin(this.particles[i].angle)
                ));
                this.particles[i].radius*=0.996;

                let rs = p.random();
                if(this.time < this.mx_step * .05) {
                    this.time += 1;
                    return;
                }
                if(this.particles.length <= 3 && rs < 0.2 && this.time > this.mx_step * 0.2 ||
                    this.particles.length < 20 && rs < 0.01 && this.time > this.mx_step * 0.2 ||
                    this.particles.length < 10 && rs < 0.05 && this.time > this.mx_step * 0.4 ||
                    this.particles.length >= 20 && rs < 0.02 && this.particles.length < 500) {
                    let dsg = p.random() < 0.5 ? -1:1;
                    this.particles.push(
                        new TreeParticle(
                            this.particles[i].pos.x,
                            this.particles[i].pos.y,
                            this.particles[i].angle + dsg * (p.TWO_PI/30 + p.random(p.TWO_PI/30)),
                            this.particles[i].radius*p.random(.8, .9)
                        )
                    )
                }
            }
            this.time += 1;
        }

        display(){
            G.noStroke();
            if(this.time >= this.mx_step) {
                if(this.time > this.mx_step+this.additional_step) return;
                //leaf
                for(let i=0;i<this.particles.length;++i){
                    if(this.particles[i].pos.y > this.init_y){continue;}
                    G.blendMode(p.ADD);
                    let col = p.color(
                        p.random(this.white_v, 250) * this.base_leaf[0],
                        p.random(this.white_v, 250) * this.base_leaf[1],
                        p.random(this.white_v, 250) * this.base_leaf[2],
                        40
                    );
                    G.fill(col);
                    G.circle(this.particles[i].pos.x, this.particles[i].pos.y, this.particles[i].radius);

                    col.setAlpha(20);
                    G.fill(col);
                    G.circle(this.particles[i].pos.x, this.init_y*1.5 - this.particles[i].pos.y*.5, this.particles[i].radius*.75);
                }
                return;
            }
            //branch
            for(let i=0;i<this.particles.length;++i){
                if(this.particles[i].radius < this.width*0.006) {
                    continue;
                }
                let ratio = this.time/this.mx_step;
                let os = ratio*(p.noise(this.particles[i].pos.x*this.nscale, this.particles[i].pos.y*this.nscale) - .5)*this.width/3;
                let pr = this.particles[i].radius;

                pr *= p.map(p.pow(ratio, 0.5), 0, 0.41, 5, 1, true);
                G.blendMode(p.ADD);
                this.branch_color.setAlpha(20);
                G.fill(this.branch_color);
                G.circle(this.particles[i].pos.x, this.particles[i].pos.y, pr);

                let fm = ratio;
                if(this.particles[i].pos.y < this.init_y){
                    G.blendMode(p.DODGE);
                    this.branch_color.setAlpha(40);
                    G.fill(this.branch_color);
                    G.circle(
                        this.particles[i].pos.x + os,
                        this.init_y*1.5 - this.particles[i].pos.y*.5,
                        pr);//this.particles[i].radius);
                }
                let sr = p.max(this.particles[i].radius, this.width*0.03);

                if(ratio > 0.4 && p.random() < 0.05){
                    var sr = p.max(this.particles[i].radius, this.width*0.01);
                    G.blendMode(p.ADD);
                    let scol = p.color(
                        p.random(10, 255),
                        p.random(10, 255),
                        p.random(10, 255),
                        255
                    );
                    G.fill(scol);
                    G.circle(
                        this.particles[i].pos.x,
                        this.particles[i].pos.y,
                        sr * .3
                    )
                    if(this.particles[i].pos.y < this.init_y){
                        scol.setAlpha(150);
                        G.fill(scol);
                        G.circle(
                            this.particles[i].pos.x,
                            this.init_y*1.5 - this.particles[i].pos.y*.5,
                            sr * .2
                        )
                    } 
                }

                for(let j=0;j<this.sub_colors.length;++j){
                    var osx = p.random(-.5, 0.5);
                    G.blendMode(p.ADD);
                    let ss = p.random();
                    if(ratio < 0.2 && ss < .2 || ratio >= 0.2 && ss < .95){continue;}
                    this.sub_colors[j].setAlpha(250);
                    G.fill(this.sub_colors[j]);
                    G.circle(
                        this.particles[i].pos.x + this.sub_offset[j] * pr + osx* pr,
                        this.particles[i].pos.y + osx* pr*fm,
                        this.sub_radius[j] * sr
                    )
                    if(this.particles[i].pos.y < this.init_y){
                        G.blendMode(p.ADD);
                        this.sub_colors[j].setAlpha(80);
                        G.fill(this.sub_colors[j]);
                        G.circle(
                            this.particles[i].pos.x + this.sub_offset[j] * pr + os + osx * pr,
                            this.init_y*1.5 - this.particles[i].pos.y*.5 + osx* pr*fm,
                            this.sub_radius[j] * sr
                        )
                    }

                    if(ratio<0.18){
                        for(let k=0;k<10;++k){
                            osx = p.random(-.5, 0.5);
                            let rdm = p.random(0.3, 0.7);
                            this.sub_colors[j].setAlpha(200);
                            G.blendMode(p.ADD);
                            G.fill(this.sub_colors[j]);
                            G.circle(
                                this.particles[i].pos.x + this.sub_offset[j] * pr + osx* pr,
                                this.particles[i].pos.y + osx* pr*fm,
                                this.sub_radius[j] * sr * rdm
                            )
                            G.blendMode(p.DODGE);
                            if(this.particles[i].pos.y < this.init_y){
                                this.sub_colors[j].setAlpha(150);
                                G.fill(this.sub_colors[j]);
                                G.circle(
                                    this.particles[i].pos.x + this.sub_offset[j] * pr + os + osx * pr,
                                    this.init_y*1.5 - this.particles[i].pos.y*.5 + osx* pr*fm,
                                    this.sub_radius[j] * sr * rdm
                                )
                            }
                        }
                    }
                    if(ratio<0.01){
                        for(let k=0;k<10;++k){
                            osx = p.random(-1.2, 1.2);
                            var rdm = p.random(0.3, 0.7);
                            this.sub_colors[j].setAlpha(200);
                            G.blendMode(p.ADD);
                            G.fill(this.sub_colors[j]);
                            G.circle(
                                this.particles[i].pos.x + this.sub_offset[j] * pr + osx* pr,
                                this.particles[i].pos.y + osx* pr*fm,
                                this.sub_radius[j] * sr * rdm
                            )
                            if(this.particles[i].pos.y < this.init_y){
                                this.sub_colors[j].setAlpha(150);
                                G.blendMode(p.DODGE);
                                G.fill(this.sub_colors[j]);
                                G.circle(
                                    this.particles[i].pos.x + this.sub_offset[j] * pr + os + osx * pr,
                                    this.init_y*1.5 - this.particles[i].pos.y*.5 + osx* pr*fm,
                                    this.sub_radius[j] * sr * rdm
                                )
                            }
                        }
                    }
                }
            }
        }
    }
    class TreeParticle {
        pos;
        angle;
        radius;
        constructor(x, y, a, r){
            this.pos = p.createVector(x, y);
            this.angle = a;
            this.radius = r;
        }
    }

    class Star {
        pos;
        radius;
        color;
        time;
        t;
        constructor(){
            let ag = p.random(0, p.PI);
            let r = p.random(p.height*SPL*.7, p.height*SPL*1.5);
            this.pos = p.createVector(
                r*p.cos(ag)*p.width/p.height/SPL*.4 + p.width/2,
                p.height*SPL - r*p.sin(ag)
            );
            this.radius = p.random(min_width/400, min_width/150);
            this.time = p.int(p.random(120, 360));
            this.t=0;
            this.color = p.color(
                p.random(10, 255),
                p.random(10, 255),
                p.random(10, 255),
                255
            );
        }
        display() {
            if(this.t == this.time){
                this.t = 0;
                this.color = p.color(
                    p.random(10, 255),
                    p.random(10, 255),
                    p.random(10, 255),
                    255
                );
                this.time = p.int(p.random(120, 360));
                this.radius = p.random(min_width/400, min_width/150);
                var ag = p.random(0, p.PI);
                var r = p.random(p.height*SPL*.7, p.height*SPL*1.5);
                this.pos = p.createVector(
                    r*p.cos(ag)*p.width/p.height/SPL*.4 + p.width/2,
                    p.height*SPL - r*p.sin(ag)
                );
            }
            p.blendMode(p.ADD);
            let rt = this.t/this.time;
            this.color.setAlpha((1-p.cos(rt*p.TWO_PI))*255);
            p.strokeWeight(1);

            p.stroke(this.color);
            this.color.setAlpha((1-p.cos(rt*p.TWO_PI))*100);
            p.fill(this.color);
            p.circle(this.pos.x, this.pos.y, this.radius);

            this.color.setAlpha((1-p.cos(rt*p.TWO_PI))*127);
            p.stroke(this.color);
            this.color.setAlpha((1-p.cos(rt*p.TWO_PI))*50);
            p.fill(this.color);
            p.circle(
                this.pos.x,
                p.height*SPL*1.5 - this.pos.y*.5,
                this.radius * 0.7
            )
            this.t += 1;
            p.noStroke();
        }
    }
};

new p5(sketch);

